INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Grilled Cheese', 'grilled-cheese', ARRAY['Toasted cheese sandwich', 'Cheese toastie', 'Cheese jaffle']::text[], 'Cheese melted between two slices of bread that are browned in butter or mayonnaise.', 'A grilled cheese is a cheese sandwich cooked in a pan, on a griddle, or in a pie iron until the bread browns and the cheese melts. The outside of the bread is usually spread with butter or mayonnaise, and despite the name the sandwich is rarely made by grilling. Cheddar and American cheese are the most common fillings, though provolone and gouda are also used.

An 1861 English recipe book, Mrs. Beeton''s Book of Household Management, describes brown bread and butter sandwiches filled with cheese and put in an oven until the bread toasted. The open-faced cheese dream became popular in the United States during the Great Depression, and U.S. government cookbooks describe Navy cooks grilling "American cheese filling sandwiches" during World War II. It can also be cooked in a pie iron or sandwich toaster, which seals the edges of the sandwich. In the United Kingdom it is usually called a cheese toastie, and in Australia a cheese jaffle, after the jaffle iron patented there in 1949 by Dr. Ernest Eric Smithers of Bondi. Breville''s Snack''n''Sandwich Toaster, introduced in 1974, became so popular in Australia that the brand name is sometimes used for the sandwich itself, while in Britain a 2005 survey found that 45% of adults owned a sandwich toaster but did not use it.', NULL, 'Global', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"American"}],"condiments":[{"name":"Butter"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/6_qJojDsf2F5VohZ_zyke-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Patty Melt', 'patty-melt', ARRAY[]::text[], 'A beef patty with melted Swiss cheese and caramelized onions on griddled rye bread.', 'A patty melt is a grilled hamburger: a ground beef patty with melted cheese, traditionally Swiss, and caramelized onions between two slices of griddled bread, typically caraway rye or marbled rye. It is usually made without condiments. Hamburger patties served between slices of bread instead of a bun date to the mid-1800s, but it is unclear exactly when the patty melt was invented, most likely in the mid-20th century.

Los Angeles restaurateur Tiny Naylor is sometimes credited with inventing it, and it was on the menu at Tiny Naylor''s in the early 1950s. Even if he did not invent it, his restaurants helped popularize the sandwich. It is a fixture of diners, coffee shops, and lunch counters, and is little known outside the United States.', 'United States', 'Americas', '{"bread":[{"name":"Rye"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Ground beef patty"}],"toppings":[{"name":"Caramelized Onions"}]}'::jsonb, ARRAY[]::text[], NULL, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Tuna Melt', 'tuna-melt', ARRAY[]::text[], 'Tuna salad and melted cheese on toasted bread, served hot.', 'A tuna melt is a melt sandwich made with tuna salad, canned tuna mixed with mayonnaise and often pickles, tomato, or onion, topped with melted cheese on toasted bread. It grew out of the tuna fish sandwich, which was already served in American homes in the 19th century and grew steadily more popular in the early 20th century as canned tuna, mayonnaise, and sliced bread became widely available.

The New York Times printed a recipe for the melted-cheese version in 1951 under the name "tuna sandwich au gratin." Along with the patty melt, the tuna melt is a staple of the traditional American diner.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"American"}],"protein":[{"name":"Tuna Salad"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['pescatarian']::text[], NULL, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Croque Monsieur', 'croque-monsieur', ARRAY[]::text[], 'A French hot ham and cheese sandwich on pain de mie, topped with grated cheese and baked or fried; some brasseries add béchamel.', 'A croque monsieur is a hot ham and cheese sandwich. The name combines croquer, "to crunch," with monsieur, "mister." It is traditionally made with baked or boiled ham and sliced cheese between slices of pain de mie, topped with grated cheese, then baked or fried so the cheese melts into a crust. Gruyère is traditional, though Comté or Emmental are sometimes used, and some brasseries add béchamel sauce.

References to the sandwich appear before the end of the 19th century. An 1891 article in La Revue Athlétique describes friends making croque-monsieurs with toast, butter, Gruyère, ham, and a little cayenne pepper.', 'France', 'Europe', '{"bread":[{"name":"Pain de mie"}],"cheese":[{"name":"Gruyere"}],"protein":[{"name":"Ham"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/rQgHyPBygRMeK7Z2fPHuv-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Croque Madame', 'croque-madame', ARRAY['Croque-à-cheval']::text[], 'A croque monsieur topped with a fried or poached egg.', 'A croque madame is a croque monsieur served with a poached or lightly fried egg on top. In parts of Normandy it is known as a croque-à-cheval. According to the Petit Robert dictionary, the name dates to around 1960.

Chef Jacques Pépin maintains that a croque madame is made with chicken in place of ham. A lighter vegetarian version, made with ordinary melting cheese, chives, cucumber, and lettuce, is called a croque-mademoiselle.', 'France', 'Europe', '{"bread":[{"name":"Pain de mie"}],"cheese":[{"name":"Gruyere"}],"protein":[{"name":"Ham"},{"name":"Fried Egg"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/zyZ0nZQLITPqMmLe4VTxO-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Monte Cristo', 'monte-cristo', ARRAY[]::text[], 'A ham and cheese sandwich dipped in beaten egg and pan-fried, often dusted with powdered sugar and served with jam or syrup.', 'A Monte Cristo is a ham and cheese sandwich dipped in beaten egg and pan-fried, a variation on the French croque monsieur. The first documented reference to a Monte Cristo sandwich is in a 1923 American restaurant industry publication, despite the common claim that it was developed in Southern California in the 1960s.

From the 1930s to the 1960s, American cookbooks commonly carried recipes for similar sandwiches under names such as "French sandwich," "toasted ham sandwich," and "French toasted cheese sandwich." It was especially popular in Southern California and became more widely known after the Blue Bayou Restaurant at Disneyland began serving it. Sweeter versions are dusted with powdered sugar and served with maple syrup or preserves, and regional variations may add sliced turkey or caramelized onions.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Ham"}],"chefs-special":[{"name":"Powdered sugar"},{"name":"Maple syrup"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/bVBqIMUJ4q-X5jYohaXhw-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Reuben', 'reuben', ARRAY[]::text[], 'Corned beef, Swiss cheese, sauerkraut, and Russian or Thousand Island dressing on grilled rye.', 'The Reuben is an American grilled sandwich of corned beef, Swiss cheese, sauerkraut, and Russian or Thousand Island dressing on rye. Its origins are disputed.

One story credits Reuben Kulakofsky, a Lithuanian-born Omaha grocer who asked for a corned beef and sauerkraut sandwich at a weekly poker game held at the Blackstone Hotel from around 1920 to 1935. The hotel owner''s son, working in the kitchen, is said to have added Swiss cheese and Thousand Island dressing on rye. The hotel put it on its lunch menu, and its fame spread when a former Blackstone employee won a national sandwich idea contest with the recipe. Another account credits Arnold Reuben of Reuben''s Delicatessen in New York City, who according to an interview with Craig Claiborne created the "Reuben Special" around 1914.

Because it combines meat and dairy, the Reuben is not kosher, though it is common at kosher-style delicatessens.', 'United States', 'Americas', '{"bread":[{"name":"Rye"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Corned Beef"}],"toppings":[{"name":"Sauerkraut"}],"condiments":[{"name":"Russian Dressing"}]}'::jsonb, ARRAY[]::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/y0JlyXzCVMJ-ZuEj_zvIt-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Rachel', 'rachel', ARRAY['Georgia Reuben', 'California Reuben']::text[], 'A Reuben variation with turkey or pastrami in place of the corned beef and coleslaw in place of the sauerkraut.', 'The Rachel is a variation of the Reuben that substitutes pastrami or turkey for the corned beef and coleslaw for the sauerkraut. Its exact origin is unclear, but the name may come from the 1871 song "Reuben and Rachel."

In some parts of the United States, especially Michigan, the turkey version is known as a "Georgia Reuben" or "California Reuben" and may use barbecue sauce or French dressing in place of Russian dressing. A related sandwich, the Dinty Moore, swaps the sauerkraut for coleslaw and is particularly popular around Detroit.', 'United States', 'Americas', '{"bread":[{"name":"Rye"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Turkey"}],"toppings":[{"name":"Coleslaw"}],"condiments":[{"name":"Russian Dressing"}]}'::jsonb, ARRAY[]::text[], NULL, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Cubano', 'cubano', ARRAY['Cuban sandwich', 'Cuban mix', 'Mixto', 'Cuban pressed sandwich']::text[], 'Roast pork, ham, Swiss, pickles, and mustard pressed on Cuban bread.', 'The Cuban sandwich is made with roast pork, ham, Swiss cheese, dill pickles, and yellow mustard on Cuban bread, pressed in a plancha until the bread is crisp and the cheese has begun to melt. It likely originated before 1900 in cafés serving Cuban workers in Tampa or Key West, two Florida cigar-industry centers, though its exact origin is murky. Some believe it was already a lunch staple for cigar and sugar workers in Cuba by the 1860s, and historian Loy Glenn Westfall called it "born in Cuba and educated in Key West." The earliest recorded mentions of a distinct Cuban sandwich come from workers'' cafés in Ybor City around 1900.

After Fidel Castro''s 1959 rise to power, an influx of Cuban exiles made the sandwich common in Miami as well. Tampa''s version traditionally includes Genoa salami, likely because of the city''s Italian immigrants, while South Florida''s usually leaves it out, the center of a friendly Tampa-Miami rivalry. In 2012 the Tampa City Council named the "Historic Tampa Cuban Sandwich" the city''s signature sandwich.', 'United States', 'Americas', '{"bread":[{"name":"Cuban bread"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Roast pork"},{"name":"Ham"}],"toppings":[{"name":"Pickles"}],"condiments":[{"name":"Mustard"},{"name":"Butter"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/CFqF6l4eOMvrdPsm3Ne-P-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Mozzarella in Carrozza', 'mozzarella-in-carrozza', ARRAY['Carrozza']::text[], 'A mozzarella sandwich coated in egg and flour and fried.', 'Mozzarella in carrozza, "mozzarella in a carriage," is a fried cheese sandwich in Italian cuisine. A mozzarella sandwich is coated in egg and flour and fried, usually in olive oil, until crisp. It is often served as an antipasto.

It is a popular street food in Campania, where it is typically made with buffalo mozzarella, and a popular dish in Italian-American restaurants in New York City, where it is usually deep fried. Some versions add ham, anchovies, eggplant, green tomatoes, or basil.', 'Italy', 'Europe', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Mozzarella"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian']::text[], NULL, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('BLT', 'blt', ARRAY[]::text[], 'Bacon, lettuce, and tomato, often with mayonnaise, between slices of toasted bread.', 'A BLT is a sandwich named for the initials of its main ingredients: bacon, lettuce, and tomato. There is little evidence of BLT recipes before 1900. A club sandwich recipe in the 1903 Good Housekeeping Everyday Cook Book already combined bacon, lettuce, tomato, mayonnaise, and turkey, while a 1928 book of bacon sandwiches, Seven Hundred Sandwiches, includes no recipe with tomato.

The BLT became popular after World War II, when the rapid growth of supermarkets made its ingredients available year-round. The initials likely began as restaurant shorthand in the United States, but it is unclear when they entered everyday use. A 1951 Saturday Evening Post passage describes the sandwich without the initials, and by 1958 a Hellmann''s advertisement called mayonnaise traditional on bacon, lettuce, and tomato sandwiches. In a 2019 YouGov poll it was the fifth most popular sandwich in the United States.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Bacon"}],"toppings":[{"name":"Lettuce"},{"name":"Tomato"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['dairy_free', 'contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/u4Ba0l2_0v9M07v4VNKUj-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Club Sandwich', 'club-sandwich', ARRAY['Clubhouse sandwich']::text[], 'A three-layer sandwich of toasted bread with sliced turkey or chicken, bacon, lettuce, tomato, and mayonnaise, often cut into quarters.', 'A club sandwich, or clubhouse sandwich, is a three-layer sandwich of toasted bread with sliced poultry, fried bacon, lettuce, tomato, and mayonnaise. It is often cut diagonally into quarters or halves and held together with cocktail sticks.

Its origin is disputed. The earliest known reference, an 1889 article in The Evening World, describes a "Union Club sandwich" of turkey or chicken and ham between two toasted slices of Graham bread, and several other early references credit the chef of the Union Club of New York City. Another theory places its invention at the Saratoga Club in Saratoga Springs, New York, after Richard Canfield bought it and turned it into the Canfield Casino in 1894. The sandwich appeared on American restaurant menus by 1899, and the earliest reference in published fiction is from 1903. Early versions used chicken, but turkey has become increasingly common.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Turkey"},{"name":"Bacon"}],"toppings":[{"name":"Lettuce"},{"name":"Tomato"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['dairy_free', 'contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Peanut Butter and Jelly', 'peanut-butter-and-jelly', ARRAY['PB&J', 'PBJ']::text[], 'Peanut butter and fruit jelly or jam spread on sandwich bread.', 'A peanut butter and jelly sandwich, often written PB&J, is peanut butter and fruit preserves spread on sliced bread. It is typically associated with grape jelly and white bread and is known for its popularity among children in the United States. Its origin is disputed, though it is understood to be an American invention.

The first published mention appeared in a 1901 issue of the Boston Cooking School Magazine, where Julia Davis Chandler suggested tea sandwiches made with peanut butter, which she called "peanut paste," and currant or crab-apple jelly. She believed the recipe to be original. At the time, peanut butter was considered a delicacy, and by 1913 the New York Times was recommending peanut and jelly sandwiches for children''s school lunches.

The invention of sliced bread and developments in peanut butter manufacturing, both in 1928, helped make the sandwich more common. It was a frequent meal for families in need during the Great Depression, and American soldiers sometimes ate it because its ingredients keep well. It became a major dish of American cuisine in the 1950s and 1960s. Concern about peanut allergies has since reduced its place in school lunches.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Peanut Butter"}],"condiments":[{"name":"Jelly"}]}'::jsonb, ARRAY['vegan', 'vegetarian', 'pescatarian', 'dairy_free', 'contains_peanuts']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Ham and Cheese', 'ham-and-cheese', ARRAY[]::text[], 'Sliced ham and cheese on bread, served cold or toasted.', 'A ham and cheese sandwich pairs sliced cooked ham with cheese between slices of bread and may be served cold or toasted. Its origin has been debated, and no single point of origin is established. A 1924 interview with ballpark concessionaire Harry Stevens recalled that in 1894 ham and cheese sandwiches were the only food sold at New York baseball parks, with frankfurters introduced in 1909. An Englishwoman who passed through Ellis Island in 1923 described porters bringing baskets of ham and cheese sandwiches to arriving immigrants, and Richard E. Byrd took them on his 1926 polar flight.

The pairing is the base of many regional variations, including France''s croque monsieur, Brazil''s misto-quente, and the Cuban sandwich. In the United Kingdom a common addition is pickle, and the British Sandwich Association says the ham sandwich is the country''s most popular.', NULL, 'Global', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Swiss"}],"protein":[{"name":"Ham"}],"toppings":[{"name":"Lettuce"}],"condiments":[{"name":"Mustard"},{"name":"Mayo"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/fTy16FI3bS5uMJIa0uvAb-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Roast Beef', 'roast-beef', ARRAY[]::text[], 'Thinly sliced roast beef on bread or a roll, served hot or cold, often with horseradish.', 'A roast beef sandwich is made with sliced roast beef, frequently cold leftovers or deli meat, and may be served hot, cold, or open-faced. Roast beef sandwiches have been eaten since the 19th century: John Keats mentions enjoying them on a walking tour of Scotland in 1818, and some trace the modern American style to an 1877 recipe for "beefsteak toast," a dish of cold beef, bread, and gravy.

The sandwich has regional specialties. The Boston area, particularly the North Shore of Massachusetts, has served roast beef sandwiches since the early 1950s, typically very rare, thinly sliced, and piled on an onion roll. In the United Kingdom it is often served hot with fried onions, gravy, and horseradish sauce. In the United States it is sold at many diners and at chains such as Arby''s, which opened in 1964 and at first served only roast beef sandwiches, potato chips, and soft drinks.', NULL, 'Global', '{"bread":[{"name":"Kaiser Roll"}],"cheese":[{"name":"Cheddar"}],"protein":[{"name":"Roast Beef"}],"toppings":[{"name":"Onion"},{"name":"Lettuce"}],"condiments":[{"name":"Horseradish"}]}'::jsonb, ARRAY[]::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Philly Cheesesteak', 'philly-cheesesteak', ARRAY['Cheesesteak', 'Philadelphia cheesesteak', 'Steak and cheese']::text[], 'Thinly sliced griddled beef with melted cheese on a long roll.', 'A cheesesteak is a sandwich of thinly sliced beefsteak, often rib eye, and melted cheese on a long hoagie roll. It has its roots in Philadelphia. Pat and Harry Olivieri, who opened a hot dog stand in South Philadelphia in 1930, are often credited with inventing it by serving chopped steak with grilled onions on an Italian roll, a story the family dates to 1933. The exact story is debated. The stand grew into Pat''s King of Steaks.

The sandwich was originally made without cheese. According to Pat''s son Herb Olivieri, American cheese was first added in 1951 by a manager known as "Cocky Joe" Lorenza, though others say it was provolone. Cheez Whiz, first marketed in 1952, was added at Pat''s South Philadelphia location in the late 1950s, and provolone, American cheese, and Cheez Whiz remain the most common choices. Geno''s Steaks opened across the street in 1966, starting a long rivalry. Today the cheesesteak is a signature dish of Philadelphia.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"cheese":[{"name":"Cheese Whip"}],"protein":[{"name":"Steak"}],"toppings":[{"name":"Sautéed Onions"}]}'::jsonb, ARRAY[]::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Italian Sub', 'italian-sub', ARRAY['Italian hoagie', 'Italian hero', 'Italian grinder']::text[], 'A long roll filled with Italian cold cuts, provolone, vegetables, and oil and vinegar.', 'A submarine sandwich, or sub, is an American sandwich made on a long roll split lengthwise and filled with meats, cheeses, vegetables, and condiments. The type originated in several Italian-American communities in the northeastern United States between the late 19th and mid-20th centuries and spread as pizzerias added it to their menus. The Italian sub is the classic cold-cut version, with salami and other cured meats, cheese, peppers, and an oil and vinegar dressing.

The name varies by region: hoagie in Philadelphia, hero in New York City, grinder in much of New England, wedge in parts of the New York suburbs, and simply "Italian" in Maine. The origins of these names are disputed. One explanation ties "hoagie" to Italian-American workers at Philadelphia''s Hog Island shipyard, and "hero" is first attested in 1937. According to his granddaughter, Dominic Conti, an Italian immigrant who opened a grocery in Paterson, New Jersey, around 1910, sold a long roll filled with cold cuts, vegetables, oil, vinegar, and herbs. This encyclopedia treats the regional names as aliases of one sandwich.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"cheese":[{"name":"Provolone"}],"protein":[{"name":"Salami"},{"name":"Capicola"},{"name":"Ham"},{"name":"Mortadella"}],"toppings":[{"name":"Lettuce"},{"name":"Tomato"},{"name":"Onion"},{"name":"Hot Peppers"}],"condiments":[{"name":"Olive Oil & Vinegar"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/-pfcb2pDuoR8UkoVE4IT_-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Meatball Sub', 'meatball-sub', ARRAY['Meatball sandwich', 'Meatball hero']::text[], 'Meatballs in marinara sauce with melted cheese on a long roll.', 'A meatball sandwich is made with meatballs, typically of beef or pork, in a tomato sauce such as marinara on bread, often with a cheese such as provolone or mozzarella. It is part of Italian-American and American cuisine and is sometimes prepared as a submarine sandwich.

It has been suggested that the meatball sandwich was invented in the United States around the turn of the 20th century, though the specific location is disputed. In New York, pizzeria menus often list meatball heros alongside eggplant and chicken parmigiana, each served with sauce.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"cheese":[{"name":"Provolone"},{"name":"Parmesan"}],"protein":[{"name":"Meatballs"}],"condiments":[{"name":"Marinara Sauce"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/apMRTM0mXG2OBvN0bqGzB-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Chicken Parm Sub', 'chicken-parm-sub', ARRAY['Chicken parmesan sandwich', 'Chicken parmigiana sandwich', 'Chicken parm hero']::text[], 'A breaded chicken cutlet with marinara and melted mozzarella on a long roll.', 'Chicken parmesan, or chicken parm, is fried breaded chicken breast covered in tomato sauce and mozzarella, Parmesan, or provolone. It originated in the Italian diaspora in the United States in the early 20th century. It has been speculated that it combines parmigiana, the Italian dish of fried eggplant slices in tomato sauce, with the cotoletta, a breaded veal cutlet that in Italy is generally served without sauce or cheese.

Italian immigrants in the northeastern United States began using chicken in parmigiana, and by the 1950s it was a staple of Italian-American restaurants. The New York Times published a recipe in 1962. Many restaurants also offer chicken parm as a sandwich, and New York pizzerias list it as a hero served with sauce.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"cheese":[{"name":"Mozzarella"},{"name":"Parmesan"}],"protein":[{"name":"Fried Chicken"}],"condiments":[{"name":"Marinara Sauce"}]}'::jsonb, ARRAY[]::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/mddFOQuly9HFydKfoLTmd-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('French Dip', 'french-dip', ARRAY['Beef dip']::text[], 'Thinly sliced roast beef on a French roll or baguette, served with a cup of beef juice for dipping.', 'A French dip is a hot sandwich of thinly sliced roast beef on a "French roll" or baguette, usually served with a cup of beef juice, called au jus, for dipping. Despite the name it is an American invention and is almost unknown in France; the name seems to refer to the style of bread.

Two Los Angeles restaurants, Cole''s Pacific Electric Buffet and Philippe the Original, both established in 1908, claim to have created it. Cole''s says a chef named Jack Garlinghouse invented it shortly after the restaurant opened, while Philippe''s says owner Philippe Mathieu invented it in 1918, in one version when a sandwich was accidentally dropped into a pan of meat drippings. Neither restaurant cites period references, and the dispute is unresolved. A November 1929 magazine mention of a Los Angeles eatery called the Dugout may be the first in print.', 'United States', 'Americas', '{"bread":[{"name":"French Roll"}],"protein":[{"name":"Roast Beef"}],"condiments":[{"name":"Au Jus"},{"name":"Mustard"}]}'::jsonb, ARRAY[]::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Sloppy Joe', 'sloppy-joe', ARRAY[]::text[], 'Ground beef with onions in a tomato sauce or ketchup, piled on a hamburger bun.', 'A sloppy joe is a sandwich of ground meat, typically beef, with onions, tomato sauce or ketchup, Worcestershire sauce, and other seasonings, served on a hamburger bun. Early and mid-20th-century American cookbooks include similar recipes under other names, such as Toasted Deviled Hamburgers, Chopped Meat Sandwiches, and Spanish Hamburgers.

Its origin is uncertain. One theory credits José "Sloppy Joe" Abeal y Otero, owner of Sloppy Joe''s Bar in Havana, who in 1917 supposedly made a sandwich of ground beef stewed in tomatoes. Another, from H.J. Heinz researchers, traces it to loose-meat sandwiches sold in Sioux City, Iowa, in the 1930s and credits a cook named Joe. References to sloppy joes as sandwiches begin in the 1940s, and food companies were selling packaged sloppy joe sauce, such as Manwich, by the 1960s.', 'United States', 'Americas', '{"bread":[{"name":"Hamburger Bun"}],"protein":[{"name":"Ground Beef"}],"toppings":[{"name":"Onion"},{"name":"Green Pepper"}],"condiments":[{"name":"Ketchup"}]}'::jsonb, ARRAY['dairy_free']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/Vo4mau1xdP01hELq_rXd4-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Egg Salad', 'egg-salad', ARRAY['Egg salad sandwich']::text[], 'Chopped hard-boiled eggs mixed with mayonnaise on bread.', 'Egg salad is chopped hard-boiled eggs bound with mayonnaise and usually mustard, often with minced celery and onion, and it is a common sandwich filling in North America and Asia. One of the earliest known printed recipes for an egg salad sandwich appears in the 1896 edition of Fannie Farmer''s Boston Cooking-School Cook Book, and a 1905 British cookbook describes several egg sandwiches, including one with chutney.

Variations are common. Jewish egg salad is made with schmaltz and onions. In Japan the same idea is the tamago sando, a mayonnaise and boiled egg sandwich, and egg salad sandwiches are a signature item in Japanese 7-Eleven stores.', NULL, 'Global', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Egg Salad"}],"toppings":[{"name":"Celery"},{"name":"Lettuce"}],"condiments":[{"name":"Mayo"},{"name":"Mustard"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian', 'dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Chicken Salad', 'chicken-salad', ARRAY['Chicken salad sandwich']::text[], 'Chopped chicken bound with mayonnaise, often with celery, on bread or a croissant.', 'Chicken salad is chopped chicken bound with mayonnaise or a similar dressing, usually with celery, onion, or other additions, and it is a common sandwich filling. In the United States and Canada the term can mean either any salad with chicken or this mixed salad of chopped chicken and a binder, often made from leftover cooked or canned chicken.

Chicken salad is older than the sandwich. A recipe in Mrs Beeton''s Book of Household Management dresses cold roast chicken with a mustard, sugar, and vinegar dressing. American recipes appear in 19th-century Southern cookbooks, including Sarah Rutledge''s The Carolina Housewife (1847), which explains how to make mayonnaise from scratch for cold meats, and Abby Fisher''s What Mrs. Fisher Knows About Old Southern Cooking (1881), which adds it to chicken and celery.', NULL, 'Global', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Chicken Salad"}],"toppings":[{"name":"Celery"},{"name":"Lettuce"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Tuna Salad', 'tuna-salad', ARRAY['Tuna fish sandwich', 'Tuna salad sandwich']::text[], 'Canned tuna mixed with mayonnaise and celery on bread.', 'A tuna salad sandwich, also called a tuna fish sandwich, is canned tuna, usually mixed with mayonnaise and sometimes celery or onion, served on sliced bread. Tuna sandwiches were already being served in American homes in the 19th century: in 1893 New York socialite Dell Montjoy Bradley included a recipe for one made with imported tuna in her cookbook Beverages and Sandwiches for Your Husband''s Friends.

Its popularity climbed in the early 20th century. Canning of tuna began in the United States around 1904, and by the 1920s canned tuna was increasingly popular as a lower-cost alternative to canned salmon. The sandwich rests on three convenience foods: canned tuna, presliced bread, and mayonnaise. In the United States, 52 percent of canned tuna is used for sandwiches. The tuna melt is a popular variation.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Tuna Salad"}],"toppings":[{"name":"Celery"},{"name":"Lettuce"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['pescatarian', 'dairy_free']::text[], NULL, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Pastrami on Rye', 'pastrami-on-rye', ARRAY[]::text[], 'Hot, thin-sliced pastrami piled on rye bread with spicy brown mustard.', 'Pastrami is a cured meat of Jewish-American cuisine, usually made from beef brisket, that originated in the Jewish community of Romania and nearby regions. Its name comes from the Yiddish pastrame, probably borrowed from Romanian pastramă. It reached the United States with Jewish immigrants from Bessarabia and Romania in the second half of the 19th century.

According to his daughter, Sussman Volk, a Lithuanian-born kosher butcher on New York''s Lower East Side, made pastrami from a Romanian friend''s recipe and in 1888 opened a delicatessen at 88 Delancey Street, one of the first delis in the city, where he served it on rye. The story is considered apocryphal but is corroborated by another writer. The sandwich became a favorite at other delis, topped with spicy brown mustard and usually served with a kosher dill pickle, and the Wall Street Journal has called it New York''s "signature sandwich." Katz''s Delicatessen on the Lower East Side, which dates its founding to 1888, is among the delis best known for it.', 'United States', 'Americas', '{"bread":[{"name":"Rye"}],"protein":[{"name":"Pastrami"}],"condiments":[{"name":"Spicy Brown Mustard"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Pulled Pork', 'pulled-pork', ARRAY['Pulled pork sandwich']::text[], 'Slow-smoked, shredded pork shoulder on a bun, often with coleslaw and barbecue sauce.', 'Pulled pork is an American barbecue dish of the Southern United States, based on pork shoulder that is slow-cooked, usually smoked over wood, shredded, and mixed with a sauce. It may be served on bread as a sandwich. For the meat to pull properly it must reach an internal temperature of about 195 to 205 °F (91 to 96 °C), and cooking commonly takes many hours. Barbecue has been part of American culture, especially in the South, since colonial times.

Styles vary. In North Carolina, Eastern-style barbecue is a whole-hog style with a thin sauce of vinegar and pepper and no tomato, and its coleslaw, made with mayonnaise, is often placed on the bun when eaten as a sandwich. Lexington, or Piedmont, style uses only the pork shoulder with a red sauce of vinegar, tomatoes, and red pepper flakes, and is typically served pulled or lightly chopped.', 'United States', 'Americas', '{"bread":[{"name":"Hamburger Bun"}],"protein":[{"name":"Pulled Pork"}],"toppings":[{"name":"Coleslaw"}],"condiments":[{"name":"BBQ Sauce"}]}'::jsonb, ARRAY['dairy_free', 'contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Brisket Sandwich', 'brisket-sandwich', ARRAY[]::text[], 'Sliced or chopped smoked beef brisket on white bread or a bun, often with pickles and onion.', 'Smoked brisket is a signature of Texas barbecue and is often considered the "national dish of Texas." Texas barbecue traces its origins to European butchery and meat-smoking traditions brought to Central Texas by German and Czech settlers in the mid-19th century. Before refrigeration, butchers smoked meat that had not sold so it would keep, and as these leftovers became popular, meat markets began to specialize in smoked meats.

At a traditional Central Texas barbecue restaurant, the meat is carved and sold by weight, and sides such as slices of white bread, dill pickle chips, and sliced onion are picked up along the line. The meat is typically rubbed with only salt and black pepper and cooked over indirect heat from a pecan, post oak, or mesquite fire, and sauce, if served, comes on the side. Brisket is a tough cut with a lot of connective tissue, so it needs long, slow cooking to become tender.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Smoked Brisket"}],"toppings":[{"name":"Pickles"},{"name":"Onion"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Fried Chicken Sandwich', 'fried-chicken-sandwich', ARRAY['Crispy chicken sandwich']::text[], 'A crispy fried chicken breast on a bun with pickles.', 'A fried chicken sandwich is fried chicken breast or thigh served between slices of bread or in a bun, typically with pickles. Chick-fil-A claims it invented the fried chicken sandwich in the 1940s, but that claim is unsubstantiated. Its southern-style chicken sandwich, served with pickles on a steamed roll and introduced on March 21, 1964, may have been the first sandwich of this style from an American fast-food chain. Burger King introduced a grilled chicken sandwich in 1990.

In August 2019 Popeyes began selling a chicken sandwich on a brioche bun with pickles and mayonnaise to compete with Chick-fil-A''s flagship sandwich. It went viral and prompted responses from nearly every major fast-food chain, in what the press called the "chicken sandwich wars." By 2024, 47% of restaurant menus featured a fried chicken sandwich, compared with 41% for burgers.', 'United States', 'Americas', '{"bread":[{"name":"Brioche"}],"protein":[{"name":"Fried Chicken"}],"toppings":[{"name":"Pickles"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY[]::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Buffalo Chicken', 'buffalo-chicken', ARRAY['Buffalo chicken sandwich']::text[], 'Fried chicken tossed in Buffalo hot sauce, with blue cheese or ranch dressing, on a bun.', 'A Buffalo chicken sandwich is fried chicken tossed in Buffalo sauce and served on a bun. Buffalo sauce is a mix of vinegar-based cayenne pepper hot sauce and melted butter. The sandwich is usually topped with lettuce, sometimes with sliced celery or tomato, and dressed with ranch or blue cheese. It brings the whole plate of Buffalo wings into one sandwich, including the cool dressing and crunchy celery that come with them, and there are no bones to deal with.

No single restaurant or cook is credited with inventing the sandwich. It grew out of Buffalo wings, which were first served in Buffalo, New York, in the 1960s and spread across the United States as bar food in the 1970s and 1980s. As the flavor caught on, restaurants started putting the sauce on boneless chicken as well, in chicken fingers, wraps, salads and sandwiches. The Buffalo chicken sandwich became a regular on bar and casual-dining menus, and fast-food chains have sold their own versions. The same pairing of hot sauce and cool dressing also shows up in Buffalo chicken pizza and Buffalo chicken dip.', 'United States', 'Americas', '{"bread":[{"name":"Hamburger Bun"}],"protein":[{"name":"Fried Chicken"}],"toppings":[{"name":"Lettuce"}],"condiments":[{"name":"Buffalo Sauce"},{"name":"Ranch"}]}'::jsonb, ARRAY[]::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/jKaks3jEIGrL9Ij0qD-hq-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Bacon Egg and Cheese', 'bacon-egg-and-cheese', ARRAY['BEC']::text[], 'Bacon, a fried or scrambled egg, and cheese on a roll or bagel, usually eaten for breakfast.', 'A bacon, egg, and cheese sandwich, often abbreviated BEC, is a breakfast sandwich made with bacon, eggs that are most often fried or scrambled, cheese, and bread, which may be buttered and toasted. It is popular in the United States and Canada and is especially significant in New York City, where it is typically served on a kaiser roll.

Many similar breakfast sandwiches use other meats, cheeses, or breads. McDonald''s Egg McMuffin, invented in 1972 by Herb Peterson, puts Canadian bacon, a griddle-fried egg, and American cheese on a toasted English muffin. Ray Kroc wrote that its arrival opened up a whole new area of business for McDonald''s, the breakfast trade.', 'United States', 'Americas', '{"bread":[{"name":"Kaiser Roll"}],"cheese":[{"name":"American"}],"protein":[{"name":"Bacon"},{"name":"Fried Egg"}],"condiments":[{"name":"Ketchup"}]}'::jsonb, ARRAY['contains_pork']::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/EA6j0ZnUbkuth6XHdJnt--1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Caprese', 'caprese', ARRAY['Caprese sandwich']::text[], 'Fresh mozzarella, tomato, and basil with olive oil on crusty bread.', 'The caprese sandwich is based on caprese salad, an Italian salad of sliced fresh mozzarella, tomatoes, and basil seasoned with salt and olive oil. It is named for the island of Capri in the Bay of Naples, Campania, where it is believed to have originated, and its green, white, and red colors match the Italian flag.

Accounts of its creation are mostly legend. One credits the Roman emperor Tiberius, and the Naples Chamber of Commerce dates the salad''s prominence on Capri to the 1920s, when the Futurist founder Filippo Tommaso Marinetti served it at dinners at the Grand Hotel Quisisana. The dish became known internationally in the 1950s, sometimes said to have followed its being served to King Farouk of Egypt on a visit; the Chamber of Commerce adds that he was served it in a roll.

In Italy caprese is often eaten as an antipasto, and its components are also used uncooked in sandwiches. Italian preparations typically omit vinegar, on the belief that it would overwhelm the delicate flavor of fresh mozzarella.', 'Italy', 'Europe', '{"bread":[{"name":"Ciabatta"}],"cheese":[{"name":"Fresh Mozzarella"}],"toppings":[{"name":"Tomato"},{"name":"Basil"}],"condiments":[{"name":"Olive Oil"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Po'' Boy', 'po-boy', ARRAY['Po-boy', 'Poor boy']::text[], 'Fried shrimp, oysters, or roast beef on a crisp, airy New Orleans French bread roll.', 'A po'' boy, short for "poor boy," is a sandwich from Louisiana, traditionally a filling of roast beef, ham, or fried seafood such as shrimp, oysters, or crawfish on a New Orleans French bread roll. This "po'' boy bread" is made with less flour and more water than a baguette, giving it a crisp crust and a light, fluffy crumb. Ordered "dressed," a po'' boy comes with shredded lettuce, sliced tomato, pickles, and mayonnaise.

Fried oyster sandwiches on French loaves, called "oyster loaves," were already known in New Orleans in the late 19th century. A popular local theory credits the name to Benny and Clovis Martin, former streetcar conductors who opened a restaurant in 1921 and served free sandwiches to striking streetcar workers in 1929, joking that each striker was "another poor boy." One New Orleans historian doubts the story: the local press did not describe it until 40 years after the strike, the brothers earlier said they made the sandwich for farmers and dock workers near the French Market, and their 1929 letter promised the strikers a meal without mentioning sandwiches.', 'United States', 'Americas', '{"bread":[{"name":"French Bread"}],"protein":[{"name":"Fried Shrimp"}],"toppings":[{"name":"Lettuce"},{"name":"Tomato"},{"name":"Pickles"}],"condiments":[{"name":"Mayo"},{"name":"Hot Sauce"}]}'::jsonb, ARRAY['pescatarian', 'contains_shellfish']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Muffuletta', 'muffuletta', ARRAY['Muffaletta']::text[], 'Italian cold cuts, provolone, Swiss, and marinated olive salad on a round Sicilian sesame loaf.', 'Muffuletta is both a round Sicilian sesame bread and the sandwich made on it. The sandwich is said to have been created in 1906 at Central Grocery on Decatur Street in New Orleans by its owner, Salvatore Lupo, a Sicilian immigrant. Another New Orleans delicatessen owner, Biaggio Montalbano, is credited with a "Roma Sandwich" that may have been a forerunner, and Progress Grocery, opened in 1924, says the sandwich''s origin is uncertain.

The traditional muffuletta is the loaf split horizontally and layered with marinated olive salad, salami, ham, Swiss cheese, provolone, and mortadella. The olive salad, a chopped mix of green and black olives, olive oil, pickled vegetables, capers, herbs, and vinegar, is its signature. It is sold in quarter, half, and full sizes and is usually served cold, though many vendors will toast it.', 'United States', 'Americas', '{"bread":[{"name":"Muffuletta Bread"}],"cheese":[{"name":"Provolone"},{"name":"Swiss"}],"protein":[{"name":"Salami"},{"name":"Ham"},{"name":"Mortadella"}],"toppings":[{"name":"Olive Salad"}],"condiments":[{"name":"Olive Oil"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Hot Brown', 'hot-brown', ARRAY['Louisville Hot Brown', 'Kentucky Hot Brown']::text[], 'An open-faced turkey and bacon sandwich covered in Mornay sauce and broiled.', 'The Hot Brown was created in 1926 at the Brown Hotel in Louisville, Kentucky, by chef Fred K. Schmidt, as an alternative to the ham and eggs served at late-night dinners. It is a variation on Welsh rarebit and one of two signature sandwiches created at the hotel shortly after it opened in 1923.

The original was sliced roast turkey on open-faced white toast, covered in Mornay sauce, sprinkled with Parmesan, and broiled until bubbly, then finished with pimento and bacon strips. Sliced roast turkey was a rarity at the time, usually reserved for holidays, and the dish soon became the choice of 95% of the restaurant''s customers. Tomato is a common garnish today. It is a local specialty of Louisville and popular throughout Kentucky, though it was unavailable at its birthplace while the Brown Hotel was closed from 1971 to 1985.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Parmesan"}],"protein":[{"name":"Turkey"},{"name":"Bacon"}],"toppings":[{"name":"Tomato"}],"condiments":[{"name":"Mornay Sauce"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Nashville Hot Chicken', 'nashville-hot-chicken', ARRAY['Hot chicken']::text[], 'Fried chicken coated in a fiery cayenne paste, served on white bread with pickles.', 'Hot chicken is a fried chicken specialty of Nashville, Tennessee. Chicken is marinated, usually in buttermilk, floured, fried, and then covered in a paste or sauce spiced with cayenne pepper; the traditional paste is three parts cayenne to one part lard. It is served on slices of white bread with pickle chips. The method comes from African American communities in the Southern United States, and spicy fried chicken has been served in Nashville''s African American communities for generations.

The dish may date to the 1930s, though the current style of spice paste may only go back to the mid-1970s. The Prince family is generally credited as its originator. Family lore holds that Thornton Prince''s girlfriend cooked him an extra-hot fried chicken breakfast as revenge for his womanizing, that he liked it, and that he and his brothers created their own recipe and opened the BBQ Chicken Shack, the business that became Prince''s Hot Chicken Shack. The story is impossible to verify.

Hot chicken has since spread to cities across the United States and abroad, and in 2016 KFC began selling "Nashville Hot Chicken" in its U.S. restaurants.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Fried Chicken"}],"toppings":[{"name":"Pickles"}],"condiments":[{"name":"Cayenne Paste"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Lobster Roll', 'lobster-roll', ARRAY[]::text[], 'Lobster meat on a grilled hot dog-style bun, served cold with mayonnaise or warm with butter.', 'A lobster roll is lobster meat served on a grilled hot dog-style bun. The filling may include butter, lemon juice, salt, and black pepper, and some parts of New England use mayonnaise in place of butter.

Credit for its invention is disputed. The Encyclopedia of American Food and Drink says it began as a hot dish at Perry''s restaurant in Milford, Connecticut, as early as 1929, while another account credits English and Portuguese fishermen and sailors. Two styles are recognized: in Maine the meat is usually served cold with mayonnaise, while the hot, buttered version is known as Connecticut style. By 1970 roadside stands such as Red''s Eats in Maine were serving lobster heated in drawn butter on a hot dog bun. Lobster rolls are most associated with Maine but are common across New England and on eastern Long Island, and McDonald''s in parts of Canada and New England sometimes sells them as a summer item.', 'United States', 'Americas', '{"bread":[{"name":"Hot Dog Bun"}],"protein":[{"name":"Lobster"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['pescatarian', 'contains_shellfish']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Chopped Cheese', 'chopped-cheese', ARRAY['Chop cheese']::text[], 'Ground beef, onions, and melted cheese chopped together on a grill and served on a hero roll.', 'The chopped cheese is a New York City bodega sandwich, found mainly in uptown Manhattan and the Bronx. Ground beef, usually from pre-formed patties, is cooked on a grill with onions and seasonings such as adobo, and chopped together with cheese as it melts. It is served on a hero roll with lettuce, tomatoes, and condiments.

Its origins are debated, but most agree it was first made at Hajji''s Deli, also called Blue Sky Deli, in Spanish Harlem. Hajji''s says a former worker invented it for himself sometime in the 1990s, and some speculate that it adapts a Yemeni dish of cooked chopped meat and vegetables. The sandwich drew wide media attention in the 2010s, beginning with a 2014 episode of Anthony Bourdain''s Parts Unknown. As upscale restaurants and grocers began selling it at two to three times the bodega price, people who grew up eating it accused newcomers of "Columbusing" the sandwich.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"cheese":[{"name":"American"}],"protein":[{"name":"Ground Beef"}],"toppings":[{"name":"Onion"},{"name":"Lettuce"},{"name":"Tomato"}],"condiments":[{"name":"Ketchup"},{"name":"Mayo"}]}'::jsonb, ARRAY[]::text[], 'https://soivjezsioxaksldakiw.supabase.co/storage/v1/object/public/sandwich-images/Oc6YH98wMI-En_8jJUWU4-1600.webp', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Italian Beef', 'italian-beef', ARRAY['Chicago Italian beef']::text[], 'Thin-sliced seasoned roast beef soaked in its juices on French bread, topped with hot giardiniera or sweet peppers.', 'An Italian beef is a Chicago sandwich of very thinly sliced roast beef, simmered and served with a thin gravy on crusty French bread. It is ordered "hot," with spicy giardiniera, or "sweet," with grilled or boiled bell peppers, and the whole sandwich may be dunked in the cooking juices. Orders can be "dry," "dipped," "dunked," or "wet," though the terms vary between restaurants.

The sandwich traces back to Italian-American immigrants in Chicago as early as the 1930s, but its exact origin is unknown. One explanation is that immigrants sliced inexpensive cuts very thin to feed many people and to tenderize tougher meat. Some historians credit Pasquale Scala with inventing it in the 1920s to serve at weddings, while Al''s Beef says Tony Ferreri did; Al''s Beef itself was founded in 1938. The sandwich became ubiquitous in Chicago by the 1980s, and its popularity surged nationwide after the 2022 premiere of the television show The Bear.', 'United States', 'Americas', '{"bread":[{"name":"French Roll"}],"protein":[{"name":"Roast Beef"}],"toppings":[{"name":"Giardiniera"}],"condiments":[{"name":"Au Jus"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Beef on Weck', 'beef-on-weck', ARRAY[]::text[], 'Thin-sliced rare roast beef on a salt-and-caraway kummelweck roll with horseradish and jus.', 'A beef on weck is a sandwich of Western New York, especially Buffalo, made with thin-sliced rare roast beef on a kummelweck roll, which is topped with kosher salt and caraway seeds. The top of the roll is dipped in the jus from the roast, and horseradish is spread on it. Along with Buffalo wings and sponge candy, it is one of the three best-known food specialties of Buffalo.

Its origin is not well established, but it is thought to predate Buffalo wings by about a century. A German baker named William Wahr, believed to be from the Black Forest, is thought to have created the kummelweck roll in Buffalo, possibly basing it on a Swabian salt-and-caraway roll. A local pub owner is said to have used the roll for the sandwich because the salty top would encourage customers to buy more drinks. Kümmel is German for caraway, and Weck means "roll" in south-western German dialects.', 'United States', 'Americas', '{"bread":[{"name":"Kummelweck Roll"}],"protein":[{"name":"Roast Beef"}],"condiments":[{"name":"Horseradish"},{"name":"Au Jus"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Fried Bologna', 'fried-bologna', ARRAY['Fried bologna sandwich', 'Baloney sandwich']::text[], 'Thick-sliced bologna fried until browned, on white bread with mustard.', 'A bologna sandwich, or baloney sandwich, is bologna sausage between slices of bread with condiments such as mayonnaise, mustard, and ketchup. Bologna is an American cooked sausage derived from the Italian mortadella of Bologna.

The bologna sandwich is a regional specialty of the Eastern, Midwestern, Appalachian, and Southern United States. It is served at lunch counters of small family-run markets around the Great Smoky Mountains, and fried bologna sandwiches appear on restaurant menus in many places in the South and at some stadium concession stands, including the Cincinnati Reds''. It goes by local names: a "jumbo" in Pittsburgh and a "Lonsdale ham" sandwich in Knoxville, Tennessee. In Newfoundland and Atlantic Canada, thick-sliced fried bologna is called "Newfie steak."', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Bologna"}],"toppings":[{"name":"Onion"}],"condiments":[{"name":"Mustard"},{"name":"Mayo"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Pimento Cheese', 'pimento-cheese', ARRAY['Pimiento cheese']::text[], 'A spread of grated cheddar, mayonnaise, and chopped pimentos on white bread.', 'Pimento cheese is a spread typically made of grated cheddar, mayonnaise, and chopped pimentos, often used as a sandwich filling. Although it is most closely associated with the cuisine of the Southern United States, it began in the North in the early 20th century as a homemade snack spread. A 1908 Good Housekeeping recipe called for soft cream cheese and minced pimentos, and commercial versions had appeared by 1910. Until World War II it was mentioned in hundreds of newspaper stories and advertisements, none of which described it as Southern.

The original canned Spanish pimentos were expensive, so Southern farmers began growing pimentos, and Southern cooks adapted the recipe with hoop cheese and mayonnaise. After the war it faded in most of the country but stayed popular in the South, where it has been called the "pâté of the South." Pimento cheese sandwiches have been sold at the Masters golf tournament in Augusta, Georgia, since the 1940s.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Cheddar"}],"toppings":[{"name":"Pimentos"}],"condiments":[{"name":"Mayo"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Pork Tenderloin', 'pork-tenderloin', ARRAY['Breaded pork tenderloin sandwich', 'BPT']::text[], 'A pounded, breaded, and fried pork tenderloin cutlet that hangs well past its bun.', 'The pork tenderloin sandwich, or breaded pork tenderloin, is a breaded and fried pork cutlet similar to Wiener schnitzel, popular in the Midwestern United States, especially Indiana, Illinois, Nebraska, Missouri, and Iowa. It is claimed to have originated at Nick''s Kitchen in Huntington, Indiana, near Fort Wayne.

The pork is sliced thin, pounded with a mallet, dipped in flour, egg, and breadcrumbs or crushed saltines, and deep-fried. Unlike Wiener schnitzel, it is made only with pork and is deep-fried rather than pan-fried. It is served on a hamburger bun with the meat overhanging the bun considerably, with condiments such as mustard, ketchup, mayonnaise, lettuce, tomato, onion, and pickles, and usually with french fries or onion rings on the side.', 'United States', 'Americas', '{"bread":[{"name":"Hamburger Bun"}],"protein":[{"name":"Breaded Pork Tenderloin"}],"toppings":[{"name":"Pickles"},{"name":"Onion"},{"name":"Lettuce"}],"condiments":[{"name":"Mustard"},{"name":"Mayo"}]}'::jsonb, ARRAY['dairy_free', 'contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Fluffernutter', 'fluffernutter', ARRAY['Peanut butter and marshmallow sandwich']::text[], 'Peanut butter and marshmallow creme on white bread.', 'A fluffernutter is a sandwich of peanut butter and marshmallow creme, usually on white bread. Marshmallow creme was invented in Massachusetts in the early 20th century: Amory and Emma Curtis of Melrose created Snowflake Marshmallow Creme in 1913, and Archibald Query of Somerville made his own Marshmallow Creme in 1917. In a promotional booklet sent to customers in 1918, Emma Curtis published a recipe for the "Liberty Sandwich," peanut butter and Snowflake Marshmallow Creme on oat or barley bread, the earliest known version of the sandwich.

Query sold his recipe in 1920 to H. Allen Durkee and Fred L. Mower, whose company still sells it as Marshmallow Fluff. The sandwich was not called a fluffernutter until 1960, when an advertising firm hired by Durkee-Mower coined the name. It is particularly popular in New England and has been proposed as the official state sandwich of Massachusetts.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Peanut Butter"}],"chefs-special":[{"name":"Marshmallow Creme"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian', 'dairy_free', 'contains_peanuts']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Elvis', 'elvis', ARRAY['Elvis sandwich', 'Peanut butter and banana sandwich', 'PB&B']::text[], 'Peanut butter and sliced or mashed banana on toasted bread, sometimes with bacon, often cooked in a pan.', 'The peanut butter and banana sandwich, sometimes with bacon, is often called an Elvis sandwich after Elvis Presley, who made it famous as one of his favorites. It is made with toasted bread, peanut butter, and sliced or mashed banana, and it is frequently cooked in a pan or on a griddle. Honey or jelly appears in some versions.

Presley''s fondness for peanut butter and banana sandwiches is well established, but bacon is not mentioned in every account; one book about Presley and his mother describes his favorite as peanut butter, sliced bananas, and crisp bacon. Author Dan Koeppel credits Chiquita with popularizing, or even originating, the sandwich when it distributed 90,000 recipe cards for it in 1967.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"protein":[{"name":"Peanut Butter"}],"toppings":[{"name":"Banana"}],"condiments":[{"name":"Butter"}]}'::jsonb, ARRAY['vegetarian', 'pescatarian', 'contains_peanuts']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Spiedie', 'spiedie', ARRAY[]::text[], 'Cubes of marinated, grilled meat served on soft Italian bread or a sub roll.', 'A spiedie is marinated meat, now most often chicken, threaded onto skewers, grilled over a charcoal pit, and served on soft Italian bread or a submarine roll, sometimes drizzled with fresh marinade. The marinade usually includes olive oil, vinegar, Italian spices, and fresh mint. Spiedies are a specialty of Binghamton and Broome County in New York''s Southern Tier, and the name comes from the Italian spiedo, "spit."

Italian immigrants brought the idea to upstate New York in the early 1920s. The early Broome County spiedie was made only with spring lamb, but most restaurants now use chicken or pork. The specific origin is disputed: Camillo Iacovelli was serving spiedies at his Endicott restaurant in 1938, and his brother Augie popularized them from 1939, while Peter Sharak, who began serving them at Sharkey''s in Binghamton in 1947, is also said to have invented them. Binghamton has held the Spiedie Fest and Balloon Rally every August since 1983.', 'United States', 'Americas', '{"bread":[{"name":"Hoagie Roll"}],"protein":[{"name":"Grilled Chicken"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Loose Meat', 'loose-meat', ARRAY['Tavern sandwich', 'Loosemeat', 'Maid-Rite']::text[], 'Seasoned crumbled ground beef on a bun, without tomato sauce.', 'A loose meat sandwich, also called a tavern sandwich, is ground beef on a bun, sometimes mixed with sautéed onions and topped with pickles, ketchup, mustard, raw onions, or cheese. Unlike a hamburger, the meat is cooked loose rather than formed into a patty, so it resembles a sloppy joe without the tomato sauce.

Carroll Dietz of Missoula, Montana, created a precursor, the "steamed hamburger," in 1920. The name "tavern" is credited to David Heglin, who sold the sandwiches at his Sioux City, Iowa, restaurant in 1924; Abe Kaled bought the business in 1934, renamed it Ye Olde Tavern, and spread the sandwich across the Sioux City area. In 1926 Fred Angell, a Muscatine, Iowa, butcher, began selling his version as a "loose meat sandwich" at the first Maid-Rite restaurant. The sandwich is now known throughout the Midwest and was featured in the sitcom Roseanne.', 'United States', 'Americas', '{"bread":[{"name":"Hamburger Bun"}],"protein":[{"name":"Ground Beef"}],"toppings":[{"name":"Pickles"},{"name":"Onion"}],"condiments":[{"name":"Mustard"}]}'::jsonb, ARRAY['dairy_free']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Horseshoe', 'horseshoe', ARRAY['Horseshoe sandwich', 'Pony shoe']::text[], 'An open-faced sandwich of thick toast, a hamburger patty or ham, and fries, covered in cheese sauce.', 'The horseshoe is an open-faced sandwich from Springfield, Illinois, made of thick-sliced toast, often Texas toast, topped with a hamburger patty or other meat, French fries, and cheese sauce. Hamburger is now the most common meat, but the original was ham. The name has been attributed both to the horseshoe shape of a slice of bone-in ham and to the horseshoe-shaped arrangement of potato wedges around the ham.

The cheese sauce varies by chef but is generally derived from Welsh rarebit, with ingredients such as eggs, beer, butter, sharp cheddar, and Worcestershire sauce. A smaller portion with one slice of bread and one serving of meat is called a pony shoe, and a breakfast horseshoe swaps in sausage or bacon, eggs, and hash browns.', 'United States', 'Americas', '{"bread":[{"name":"Texas Toast"}],"cheese":[{"name":"Cheese Sauce"}],"protein":[{"name":"Ground beef patty"}],"toppings":[{"name":"French Fries"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO sandwich_database (name, slug, alternative_names, description, history, origin_country, origin_region, canonical_ingredients, dietary_tags, image_url, published)
VALUES ('Dagwood', 'dagwood', ARRAY['Dagwood sandwich']::text[], 'A towering, multi-layer sandwich stacked with meats, cheeses, vegetables, and extra slices of bread.', 'A Dagwood is a tall, multilayered sandwich made with a variety of meats, cheeses, and condiments. It is named after Dagwood Bumstead, a central character in the comic strip Blondie, who is often drawn making enormous sandwiches; according to Blondie writer Dean Young, his father, Chic Young, began drawing them in 1936. The cartoon version seems to hold cold cuts, sliced cheese, and vegetables separated by extra slices of bread, usually with a small fish such as a sardine and an olive on a toothpick on top. "Dagwood sandwich" is included in Webster''s New World Dictionary and The American Heritage Dictionary.

Restaurants have served their own versions. The Dagwood''s Sandwich Shoppes chain sold a 1.5-pound sandwich of three slices of deli bread with Genoa salami, ham, pepperoni, turkey, cheddar, provolone, lettuce, tomato, roasted red peppers, banana peppers, red onion, deli mustard, and mayonnaise. In South Africa a Dagwood is usually three slices of toasted bread with a hamburger patty, lettuce, tomato, and a fried egg.', 'United States', 'Americas', '{"bread":[{"name":"White Bread"}],"cheese":[{"name":"Cheddar"},{"name":"Provolone"}],"protein":[{"name":"Salami"},{"name":"Ham"},{"name":"Pepperoni"},{"name":"Turkey"}],"toppings":[{"name":"Lettuce"},{"name":"Tomato"},{"name":"Roasted Peppers"},{"name":"Banana Peppers"},{"name":"Red Onion"},{"name":"Olives"}],"condiments":[{"name":"Mustard"},{"name":"Mayo"}]}'::jsonb, ARRAY['contains_pork']::text[], NULL, false)
ON CONFLICT (slug) DO NOTHING;
